const axios = require('axios');
const logger = require('./logger');

class AuthService {
  constructor() {
    this.config = {
      baseUrl: process.env.MOSIP_BASE_URL || '',
      clientId: process.env.MOSIP_CLIENT_ID || '',
      secretKey: process.env.MOSIP_SECRET_KEY || '',
      authEndpoint: process.env.MOSIP_AUTH_ENDPOINT || '',
      appId: process.env.MOSIP_APP_ID || '',
      tokenUrl: process.env.MOSIP_TOKEN_URL || ''
    };
    this.token = null;
  }

  updateConfig(config) {
    if (config) {
      Object.assign(this.config, config);
      logger.debug('Auth service configuration updated');
    }
    return this;
  }

  async authenticate() {
    try {
      logger.info('Authenticating with MOSIP...');
      
      if (!this.config.baseUrl) {
        throw new Error('MOSIP base URL not configured');
      }
      
      if (!this.config.authEndpoint) {
        throw new Error('MOSIP auth endpoint not configured');
      }
      
      const requestBody = {
        id: "string",
        metadata: {},
        request: {
          appId: this.config.appId,
          clientId: this.config.clientId,
          secretKey: this.config.secretKey
        },
        requesttime: new Date().toISOString(),
        version: "string"
      };

      logger.debug('Sending authentication request', { 
        url: `${this.config.baseUrl}${this.config.authEndpoint}`,
        clientId: this.config.clientId,
        appId: this.config.appId
      });

      const response = await axios.post(
        `${this.config.baseUrl}${this.config.authEndpoint}`,
        requestBody
      );

      if (response.data.response.status === 'Success') {
        logger.info('Authentication successful');
        this.token = response.headers.authorization;
        return this.token;
      } else {
        throw new Error('Authentication failed: ' + response.data.response.message);
      }
    } catch (error) {
      logger.error('Authentication failed', { error: error.message });
      
      if (error.response) {
        logger.error('Authentication response details', {
          status: error.response.status,
          data: error.response.data
        });
      }
      
      throw error;
    }
  }

  getToken() {
    return this.token;
  }

  isAuthenticated() {
    return !!this.token;
  }
}

module.exports = new AuthService(); 